import yaml
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_3/projects/solver-trace-ablation/registry.yaml', 'r') as f:
    reg = yaml.safe_load(f)
exps = reg.get('experiments', {})
# Get SFT 1000-step data for 3 seeds
sft_exps = ['plan009-sft-baseline-s42-1000', 'plan009-sft-baseline-s43-1000', 'plan009-sft-baseline-s44-1000-r3']
total_genuine = 0
total_proved = 0
for eid in sft_exps:
    alt_ids = [eid]
    if 's43-1000' in eid:
        alt_ids.append('plan009-sft-baseline-s43-1000')
    data = None
    for aid in alt_ids:
        if aid in exps and exps[aid]:
            data = exps[aid]
            break
    if not data:
        # Try partial matches
        for k in exps:
            if 'sft' in k and '1000' in k and any(s in k for s in ['s42', 's43', 's44']):
                d = exps[k]
                if d and d.get('status') == 'DONE':
                    m = d.get('metrics', {}) or {}
                    gen = m.get('genuine_count', m.get('eval_genuine_count', '?'))
                    np_ = m.get('eval_n_proved', m.get('n_proved', '?'))
                    print(f'{k}: genuine={gen}, proved={np_}')
    else:
        m = data.get('metrics', {}) or {}
        gen = m.get('genuine_count', m.get('eval_genuine_count', '?'))
        np_ = m.get('eval_n_proved', m.get('n_proved', '?'))
        print(f'{eid}: genuine={gen}, proved={np_}')
        if isinstance(gen, (int, float)) and isinstance(np_, (int, float)):
            total_genuine += gen
            total_proved += np_

if total_proved > 0:
    print(f'\\nPooled: {total_genuine}/{total_proved} = {total_genuine/total_proved*100:.1f}%')
"

